CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE IF NOT EXISTS data_sources(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,base_url TEXT,license_url TEXT,terms_url TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS players(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,full_name TEXT NOT NULL,given_name TEXT,family_name TEXT,birth_date DATE,nationality TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS player_aliases(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,player_id BIGINT NOT NULL REFERENCES players(id) ON DELETE CASCADE,alias TEXT NOT NULL,UNIQUE(player_id,alias));
CREATE TABLE IF NOT EXISTS teams(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,country TEXT,team_type TEXT NOT NULL DEFAULT 'club' CHECK(team_type IN('club','national','other')),founded_year SMALLINT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS team_aliases(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,team_id BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,alias TEXT NOT NULL,UNIQUE(team_id,alias));
CREATE TABLE IF NOT EXISTS competitions(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,country TEXT,competition_type TEXT,gender TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seasons(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,competition_id BIGINT NOT NULL REFERENCES competitions(id),name TEXT NOT NULL,start_date DATE,end_date DATE,UNIQUE(competition_id,name));
CREATE TABLE IF NOT EXISTS matches(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,match_date TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'unknown' CHECK(status IN('scheduled','live','finished','postponed','cancelled','unknown')),home_team_id BIGINT REFERENCES teams(id),away_team_id BIGINT REFERENCES teams(id),competition_id BIGINT REFERENCES competitions(id),season_id BIGINT REFERENCES seasons(id),home_score SMALLINT CHECK(home_score IS NULL OR home_score>=0),away_score SMALLINT CHECK(away_score IS NULL OR away_score>=0),venue TEXT,source_updated_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS source_records(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,source_id BIGINT NOT NULL REFERENCES data_sources(id),entity_type TEXT NOT NULL,external_id TEXT NOT NULL,internal_id BIGINT NOT NULL,payload JSONB,fetched_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_id,entity_type,external_id));
CREATE TABLE IF NOT EXISTS match_events(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,minute SMALLINT,added_time SMALLINT,event_type TEXT NOT NULL,team_id BIGINT REFERENCES teams(id),player_id BIGINT REFERENCES players(id),assist_player_id BIGINT REFERENCES players(id),source_id BIGINT REFERENCES data_sources(id),details JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS player_match_stats(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,player_id BIGINT NOT NULL REFERENCES players(id),team_id BIGINT REFERENCES teams(id),minutes_played SMALLINT,goals SMALLINT,assists SMALLINT,shots SMALLINT,shots_on_target SMALLINT,yellow_cards SMALLINT,red_cards SMALLINT,raw_stats JSONB NOT NULL DEFAULT '{}'::jsonb,source_id BIGINT REFERENCES data_sources(id),UNIQUE(match_id,player_id,source_id));
CREATE TABLE IF NOT EXISTS team_match_stats(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,team_id BIGINT NOT NULL REFERENCES teams(id),possession NUMERIC(5,2),shots SMALLINT,shots_on_target SMALLINT,corners SMALLINT,raw_stats JSONB NOT NULL DEFAULT '{}'::jsonb,source_id BIGINT REFERENCES data_sources(id),UNIQUE(match_id,team_id,source_id));
CREATE TABLE IF NOT EXISTS videos(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,description TEXT,original_url TEXT NOT NULL,embed_url TEXT,duration_seconds INTEGER,published_at TIMESTAMPTZ,availability_checked_at TIMESTAMPTZ,embeddable BOOLEAN NOT NULL DEFAULT false,source_id BIGINT REFERENCES data_sources(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS video_match_links(video_id BIGINT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,PRIMARY KEY(video_id,match_id));
CREATE TABLE IF NOT EXISTS video_player_links(video_id BIGINT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,player_id BIGINT NOT NULL REFERENCES players(id) ON DELETE CASCADE,PRIMARY KEY(video_id,player_id));
CREATE TABLE IF NOT EXISTS import_runs(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,source_id BIGINT REFERENCES data_sources(id),started_at TIMESTAMPTZ NOT NULL DEFAULT now(),finished_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'running' CHECK(status IN('running','success','partial','failed')),records_seen INTEGER NOT NULL DEFAULT 0,records_inserted INTEGER NOT NULL DEFAULT 0,records_updated INTEGER NOT NULL DEFAULT 0,error_message TEXT);
CREATE INDEX IF NOT EXISTS players_family_name_idx ON players USING gin(family_name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS players_full_name_idx ON players USING gin(full_name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS teams_name_idx ON teams USING gin(name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS matches_date_idx ON matches(match_date DESC);
CREATE INDEX IF NOT EXISTS matches_competition_season_idx ON matches(competition_id,season_id,match_date DESC);
CREATE INDEX IF NOT EXISTS match_events_match_idx ON match_events(match_id,minute);
CREATE INDEX IF NOT EXISTS source_records_lookup_idx ON source_records(source_id,entity_type,external_id);
